const updateAutomation = `-- name: UpdateAutomation :one
UPDATE automations SET name = $1, description = $2, enabled = $3,
    trigger = $4, actions = $5, cooldown_seconds = $6,
    max_runs_per_hour = $7, updated_by = $8,
    problem = '', updated_at = now()
WHERE id = $9
RETURNING id, workspace_id, name, description, enabled, trigger, actions, cooldown_seconds, max_runs_per_hour, hook_token_hash, updated_by, created_by, created_at, updated_at, last_run_at, last_status, problem
`

type UpdateAutomationParams struct {
	Name            string     `json:"name"`
	Description     string     `json:"description"`
	Enabled         bool       `json:"enabled"`
	Trigger         []byte     `json:"trigger"`
	Actions         []byte     `json:"actions"`
	CooldownSeconds int32      `json:"cooldown_seconds"`
	MaxRunsPerHour  int32      `json:"max_runs_per_hour"`
	UpdatedBy       *uuid.UUID `json:"updated_by"`
	ID              uuid.UUID  `json:"id"`
}

// Saving clears the problem: it runs as whoever saved it now.
func (q *Queries) UpdateAutomation(ctx context.Context, arg UpdateAutomationParams) (Automation, error) {
	row := q.db.QueryRow(ctx, updateAutomation,
		arg.Name,
		arg.Description,
		arg.Enabled,
		arg.Trigger,
		arg.Actions,
		arg.CooldownSeconds,
		arg.MaxRunsPerHour,
		arg.UpdatedBy,
		arg.ID,
	)
	var i Automation
	err := row.Scan(
		&i.ID,
		&i.WorkspaceID,
		&i.Name,
		&i.Description,
		&i.Enabled,
		&i.Trigger,
		&i.Actions,
		&i.CooldownSeconds,
		&i.MaxRunsPerHour,
		&i.HookTokenHash,
		&i.UpdatedBy,
		&i.CreatedBy,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.LastRunAt,
		&i.LastStatus,
		&i.Problem,
	)
	return i, err
}
